with enriched as (select *, row_number() over (partition by manager_id order by hire_date asc, id asc) as row_seq, first_value(job_title, true) over (partition by level, job_title order by hire_date asc, id asc rows between unbounded preceding and current row) as first_known_job_title, sum(salary) over (partition by dept_id, job_title order by salary asc, id asc rows between unbounded preceding and current row) as running_salary, last_value(job_title) ignore nulls over (partition by manager_id, level order by salary asc, id asc rows between unbounded preceding and current row) as last_known_job_title, avg(salary) over (order by hire_date asc, id asc rows between 6 preceding and current row) as salary_avg_6 from employees), joined as (select a.*, e.email as employee_email, e.hire_date as employee_hire_date, e.salary as employee_salary from enriched a left join employees e on a.manager_id = e.id), metrics as (select *, row_number() over (partition by level, dept_id order by running_salary asc, id asc) as seq_no, avg(employee_salary) over (order by employee_hire_date asc, id asc rows between 2 preceding and current row) as employee_salary_avg_2, avg(salary) over (partition by level, dept_id order by running_salary asc, id asc rows between 2 preceding and 1 preceding) as salary_avg_2_prior, cume_dist() over (partition by dept_id order by employee_salary asc nulls last) as employee_salary_cume_dist, max(salary_avg_6) over (partition by manager_id) as manager_id_max_salary_avg_6 from joined), summary as (select case when employee_salary_cume_dist >= 0.85 then 'HIGH' else 'LOW' end as employee_salary_cume_dist_tier, max(row_seq) as max_row_seq, min(seq_no) as min_seq_no, approx_percentile(employee_salary_avg_2, 0.95) as employee_salary_avg_2_p95, count(*) as event_count from metrics group by rollup (case when employee_salary_cume_dist >= 0.85 then 'HIGH' else 'LOW' end)) select employee_salary_cume_dist_tier, max_row_seq, employee_salary_avg_2_p95, event_count from summary;
